    ('34898f1b-9aa7-42e2-8847-4f78639c6e67'::uuid, 'site_type', 'Mound/tumulus', 'City/town/settlement', 'fields-wd1-2026-09-26d-s006-rollback:34898f1b-9aa7-42e2-8847-4f78639c6e67:site_type', 'rollback of fields-wd1-2026-09-26d-s006: site_type ''City/town/settlement'' restored on Sohr Damb', '[{"source": "https://en.wikipedia.org/wiki/Sohr_Damb", "url": "https://en.wikipedia.org/wiki/Sohr_Damb", "quote": "The site extends around 4,5 hectares; the mound (mostly geologically formed) is 13 m high.", "outcome": "found"}, {"source": "https://www.smb.museum/en/museums-institutions/museum-fuer-islamische-kunst/collection-research/research-cooperation/reconstruction-of-an-ancient-cultural-landscape-in-baluchistan-pakistan/", "url": "https://www.smb.museum/en/museums-institutions/museum-fuer-islamische-kunst/collection-research/research-cooperation/reconstruction-of-an-ancient-cultural-landscape-in-baluchistan-pakistan/", "quote": "The results are being broadened by investigations in Sohr Damb/Nal, a 13-metre tell, and the surrounding area (2001–2007).", "outcome": "found"}, {"source": "WD1 decision (counted, round 0, wd1-r0-b0292)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia describes the 13 m high mound of Sohr Damb (''Red Mound'') and the Berlin State Museums a 13-metre tell; no source calls it a town.", "value_page": null}]'::jsonb),
